CREATE OR REPLACE FUNCTION public.apply_duty_assignment_change_for_member(p_member_id uuid, p_action text, p_slot_id uuid, p_duty_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor_id uuid := auth.uid(); v_slot record; v_registered_count integer; v_finished boolean;
begin
  if v_actor_id is null then raise exception 'You must be signed in to change a roster booking.'; end if;
  p_action := upper(coalesce(p_action, ''));
  if p_action not in ('REGISTER', 'WITHDRAW') then raise exception 'Booking action must be REGISTER or WITHDRAW.'; end if;
  if p_duty_date is null then raise exception 'A duty date is required.'; end if;
  if not exists (select 1 from public.profiles where id = p_member_id and status = 'Approved') then raise exception 'The selected JP member is not an active approved member.'; end if;
  select slot.*, desk.id as desk_id, coalesce(region.timezone, 'Pacific/Auckland') as roster_timezone into v_slot from public.duty_slots slot join public.service_desks desk on desk.id = slot.desk_id left join public.regions region on region.id = desk.region_id where slot.id = p_slot_id and slot.status = 'Active' and desk.status = 'Active' for update of slot;
  if not found then raise exception 'This duty slot is no longer active.'; end if;
  if not public.is_registrar_or_assigned_desk_admin(v_slot.desk_id) then raise exception 'You are not an assigned Desk Admin for this Service Desk.'; end if;
  if not exists (select 1 from public.duty_slot_occurrence_dates(p_slot_id,p_duty_date,p_duty_date,p_action = 'WITHDRAW') occurrence where occurrence.duty_date = p_duty_date) then raise exception 'This slot does not occur on the selected date or is closed for a holiday.'; end if;
  v_finished := p_duty_date + v_slot.end_time <= timezone(v_slot.roster_timezone, now());
  if p_action = 'REGISTER' then
    if exists (select 1 from public.duty_assignments where profile_id=p_member_id and slot_id=p_slot_id and duty_date=p_duty_date) then raise exception 'This JP member is already registered for this shift.'; end if;
    select count(*) into v_registered_count from public.duty_assignments where slot_id=p_slot_id and duty_date=p_duty_date;
    if v_registered_count >= v_slot.max_jps then raise exception 'This slot is already full.'; end if;
    delete from public.recurring_rules where profile_id=p_member_id and slot_id=p_slot_id and action='WITHDRAW' and rule_type='NEXT_N' and start_date=p_duty_date and count_n=1;
    insert into public.duty_assignments (profile_id,slot_id,duty_date) values (p_member_id,p_slot_id,p_duty_date);
  else
    if not exists (select 1 from public.duty_assignments where profile_id=p_member_id and slot_id=p_slot_id and duty_date=p_duty_date) then raise exception 'This JP member is not registered for this shift.'; end if;
    delete from public.duty_assignments where profile_id=p_member_id and slot_id=p_slot_id and duty_date=p_duty_date;
    if not v_finished then
      delete from public.recurring_rules where profile_id=p_member_id and slot_id=p_slot_id and action='WITHDRAW' and rule_type='NEXT_N' and start_date=p_duty_date and count_n=1;
      insert into public.recurring_rules (profile_id,slot_id,action,rule_type,start_date,count_n) values (p_member_id,p_slot_id,'WITHDRAW','NEXT_N'::public.rule_type,p_duty_date,1);
    end if;
  end if;
  return jsonb_build_object('action',p_action,'member_id',p_member_id,'duty_date',p_duty_date);
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_duty_assignment_change(p_action text, p_slot_id uuid, p_start_date date, p_scope text DEFAULT 'SINGLE'::text, p_count_n integer DEFAULT NULL::integer, p_until_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_profile_id uuid := auth.uid();
  v_slot record;
  v_today date;
  v_now_time time;
  v_end_date date;
  v_count_n integer;
  v_dates date[];
  v_date date;
  v_registered_count integer;
  v_shift_finished boolean;
begin
  if v_profile_id is null then raise exception 'You must be signed in to change a roster booking.'; end if;
  if not exists (select 1 from public.profiles where id = v_profile_id and status = 'Approved') then
    raise exception 'Your account is not approved for roster bookings.';
  end if;
  p_action := upper(coalesce(p_action, ''));
  p_scope := upper(coalesce(p_scope, ''));
  if p_action not in ('REGISTER', 'WITHDRAW') then raise exception 'Booking action must be REGISTER or WITHDRAW.'; end if;
  if p_scope not in ('SINGLE', 'NEXT_N', 'UNTIL_DATE', 'ALL_FUTURE') then raise exception 'Booking scope is not valid.'; end if;
  if p_start_date is null then raise exception 'A booking start date is required.'; end if;

  select slot.*, coalesce(region.timezone, 'Pacific/Auckland') as roster_timezone into v_slot
  from public.duty_slots as slot
  join public.service_desks as desk on desk.id = slot.desk_id
  left join public.regions as region on region.id = desk.region_id
  where slot.id = p_slot_id and slot.status = 'Active' and desk.status = 'Active'
  for update of slot;
  if not found then raise exception 'This duty slot is no longer active.'; end if;

  v_today := timezone(v_slot.roster_timezone, now())::date;
  v_now_time := timezone(v_slot.roster_timezone, now())::time;
  v_shift_finished := p_start_date < v_today
    or (p_start_date = v_today and coalesce(v_slot.end_time, time '00:00') <= v_now_time);
  if v_shift_finished and p_scope <> 'SINGLE' then
    raise exception 'Only a single past shift can be changed.';
  end if;

  v_count_n := least(greatest(coalesce(p_count_n, 1), 1), 52);
  if p_scope = 'UNTIL_DATE' then
    if p_until_date is null or p_until_date < p_start_date then raise exception 'Choose an end date on or after the first shift.'; end if;
    if p_until_date > p_start_date + 730 then raise exception 'The selected end date is more than two years away.'; end if;
    v_end_date := p_until_date;
  elsif p_scope = 'NEXT_N' then v_end_date := p_start_date + 730;
  elsif p_scope = 'ALL_FUTURE' then v_end_date := greatest(p_start_date, v_today) + 365;
  else v_end_date := p_start_date;
  end if;

  with candidate_dates as (
    select occurrence.duty_date
    from public.duty_slot_occurrence_dates(p_slot_id, p_start_date, v_end_date, p_action = 'WITHDRAW') as occurrence
    where (p_scope <> 'SINGLE' or occurrence.duty_date = p_start_date)
      and ((p_action = 'REGISTER' and not exists (select 1 from public.duty_assignments a where a.profile_id = v_profile_id and a.slot_id = p_slot_id and a.duty_date = occurrence.duty_date))
        or (p_action = 'WITHDRAW' and exists (select 1 from public.duty_assignments a where a.profile_id = v_profile_id and a.slot_id = p_slot_id and a.duty_date = occurrence.duty_date)))
      and (p_scope <> 'UNTIL_DATE' or occurrence.duty_date <= p_until_date)
    order by occurrence.duty_date
  ), selected_dates as (
    select duty_date from candidate_dates limit case when p_scope = 'NEXT_N' then v_count_n else 2147483647 end
  ) select array_agg(duty_date order by duty_date) into v_dates from selected_dates;
  if coalesce(array_length(v_dates, 1), 0) = 0 then raise exception 'No matching bookings were found.'; end if;

  if p_action = 'REGISTER' then
    foreach v_date in array v_dates loop
      select count(*) into v_registered_count from public.duty_assignments where slot_id = p_slot_id and duty_date = v_date;
      if v_registered_count >= v_slot.max_jps then raise exception 'The slot on % is already full. No bookings were changed.', v_date; end if;
    end loop;
  end if;

  if p_action = 'REGISTER' then
    if p_scope = 'SINGLE' then
      delete from public.recurring_rules where profile_id = v_profile_id and slot_id = p_slot_id and action = 'WITHDRAW' and rule_type = 'NEXT_N' and start_date = p_start_date and count_n = 1;
    else
      delete from public.recurring_rules where profile_id = v_profile_id and slot_id = p_slot_id and action in ('REGISTER', 'WITHDRAW');
      insert into public.recurring_rules (profile_id, slot_id, action, rule_type, start_date, until_date, count_n)
      values (v_profile_id, p_slot_id, 'REGISTER', p_scope::public.rule_type, p_start_date, case when p_scope = 'UNTIL_DATE' then p_until_date else null end, case when p_scope = 'NEXT_N' then v_count_n else null end);
    end if;
    foreach v_date in array v_dates loop
      insert into public.duty_assignments (profile_id, slot_id, duty_date) values (v_profile_id, p_slot_id, v_date) on conflict do nothing;
    end loop;
  else
    foreach v_date in array v_dates loop
      delete from public.duty_assignments where profile_id = v_profile_id and slot_id = p_slot_id and duty_date = v_date;
    end loop;
    if p_scope = 'ALL_FUTURE' then
      delete from public.recurring_rules where profile_id = v_profile_id and slot_id = p_slot_id;
    else
      foreach v_date in array v_dates loop
        -- A historical single withdrawal never needs a materialisation
        -- override: it must not leave behind a recurring-rule record.
        if not v_shift_finished then
          delete from public.recurring_rules where profile_id = v_profile_id and slot_id = p_slot_id and action = 'WITHDRAW' and rule_type = 'NEXT_N' and start_date = v_date and count_n = 1;
          insert into public.recurring_rules (profile_id, slot_id, action, rule_type, start_date, until_date, count_n)
          values (v_profile_id, p_slot_id, 'WITHDRAW', 'NEXT_N'::public.rule_type, v_date, null, 1);
        end if;
      end loop;
    end if;
  end if;
  return jsonb_build_object('action', p_action, 'scope', p_scope, 'affected_count', array_length(v_dates, 1), 'affected_dates', to_jsonb(v_dates));
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_duty_statistic_for_member(p_statistic_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_stat record;
begin
  select statistic.id,statistic.profile_id,slot.desk_id into v_stat from public.duty_statistics statistic join public.duty_slots slot on slot.id=statistic.slot_id where statistic.id=p_statistic_id;
  if not found then raise exception 'The statistics record could not be found.'; end if;
  if auth.uid() <> v_stat.profile_id and not public.is_registrar_or_assigned_desk_admin(v_stat.desk_id) then raise exception 'You are not an assigned Desk Admin for this Service Desk.'; end if;
  delete from public.duty_statistics where id=p_statistic_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_roster_operational_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare
  duty_failed integer;
  duty_waiting integer;
  desk_failed integer;
  desk_waiting integer;
  statistics_failed integer;
  statistics_waiting integer;
  monthly_failed integer;
  monthly_waiting integer;
  schedules jsonb;
begin
  if not exists (
    select 1 from public.profiles
    where id = auth.uid() and status = 'Approved' and role = 'Registrar'
  ) then
    raise exception 'Only Registrars can view roster operational health.';
  end if;

  select count(*) filter (where status = 'FAILED'),
         count(*) filter (where status in ('PENDING_CONFIRMATION', 'PROCESSING_CONFIRMATION', 'CANCELLATION_PENDING', 'PROCESSING_CANCELLATION'))
  into duty_failed, duty_waiting
  from public.duty_assignment_notifications;

  select count(*) filter (where status = 'FAILED'),
         count(*) filter (where status in ('PENDING', 'PROCESSING'))
  into desk_failed, desk_waiting
  from public.desk_admin_reminder_deliveries;

  select count(*) filter (where status = 'FAILED'),
         count(*) filter (where status in ('PENDING', 'PROCESSING'))
  into statistics_failed, statistics_waiting
  from public.duty_statistics_reminders;

  select count(*) filter (where status = 'FAILED'),
         count(*) filter (where status in ('PENDING', 'PROCESSING'))
  into monthly_failed, monthly_waiting
  from public.desk_admin_monthly_statistics_reports;

  select coalesce(jsonb_object_agg(expected.jobname, jsonb_build_object(
    'schedule', job.schedule,
    'active', coalesce(job.active, false),
    'last_status', latest.status,
    'last_started_at', latest.start_time,
    'last_finished_at', latest.end_time,
    'last_message', latest.return_message
  )), '{}'::jsonb)
  into schedules
  from (values
    ('ajpa-duty-notification-processor-minute'),
    ('ajpa-desk-admin-reminders-quarter-hourly'),
    ('ajpa-recurring-assignment-materialiser-daily'),
    ('ajpa-duty-statistics-reminder-processor-minute'),
    ('ajpa-monthly-duty-statistics-report-processor-minute')
  ) as expected(jobname)
  left join cron.job job on job.jobname = expected.jobname
  left join lateral (
    select run.status, run.start_time, run.end_time, run.return_message
    from cron.job_run_details run
    where run.jobid = job.jobid
    order by run.start_time desc
    limit 1
  ) latest on true;

  return jsonb_build_object(
    'duty_notifications', jsonb_build_object('failed', coalesce(duty_failed, 0), 'waiting', coalesce(duty_waiting, 0)),
    'desk_admin_reminders', jsonb_build_object('failed', coalesce(desk_failed, 0), 'waiting', coalesce(desk_waiting, 0)),
    'statistics_reminders', jsonb_build_object('failed', coalesce(statistics_failed, 0), 'waiting', coalesce(statistics_waiting, 0)),
    'monthly_statistics_reports', jsonb_build_object('failed', coalesce(monthly_failed, 0), 'waiting', coalesce(monthly_waiting, 0)),
    'schedules', schedules,
    'checked_at', now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.normalise_jp_warrant_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  warrant_digits text;
begin
  warrant_digits := regexp_replace(
    regexp_replace(upper(trim(coalesce(new.warrant_number, ''))), '^JP[[:space:]-]*', ''),
    '[^0-9]',
    '',
    'g'
  );

  if warrant_digits = '' then
    raise exception 'Enter the numeric part of the JP warrant number.';
  end if;

  new.warrant_number := 'JP-' || warrant_digits;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_duty_statistic_for_member(p_statistic_id uuid, p_member_id uuid, p_slot_id uuid, p_duty_date date, p_values jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_desk_id uuid;
  v_desk_name text;
  v_desk_code text;
  v_start_time time;
  v_end_time time;
  v_statistic_id uuid;
begin
  select slot.desk_id, desk.name, desk.code, slot.start_time, slot.end_time
  into v_desk_id, v_desk_name, v_desk_code, v_start_time, v_end_time
  from public.duty_slots slot
  join public.service_desks desk on desk.id = slot.desk_id
  where slot.id = p_slot_id;

  if v_actor_id is null or v_desk_id is null then
    raise exception 'A valid signed-in user and duty slot are required.';
  end if;
  if v_actor_id <> p_member_id and not public.is_registrar_or_assigned_desk_admin(v_desk_id) then
    raise exception 'You are not an assigned Desk Admin for this Service Desk.';
  end if;
  if not exists (select 1 from public.profiles where id = p_member_id) then
    raise exception 'The selected JP member does not exist.';
  end if;

  if p_statistic_id is null then
    if not exists (select 1 from public.duty_assignments where profile_id = p_member_id and slot_id = p_slot_id and duty_date = p_duty_date) then
      raise exception 'Statistics can only be added for a JP member registered for this slot.';
    end if;
    insert into public.duty_statistics (
      profile_id, slot_id, duty_date,
      desk_name_snapshot, desk_code_snapshot, start_time_snapshot, end_time_snapshot,
      no_of_clients, no_of_hours_worked, certified_copies, statutory_declarations,
      signatures_witnessed, affidavits, other_duties, notes
    ) values (
      p_member_id, p_slot_id, p_duty_date,
      v_desk_name, v_desk_code, v_start_time, v_end_time,
      coalesce((p_values->>'noOfClients')::integer, 0),
      coalesce((p_values->>'noOfHoursWorked')::numeric, 0),
      coalesce((p_values->>'certifiedCopies')::integer, 0),
      coalesce((p_values->>'statutoryDeclarations')::integer, 0),
      coalesce((p_values->>'signatureWitnessed')::integer, 0),
      coalesce((p_values->>'affidavits')::integer, 0),
      coalesce((p_values->>'other')::integer, 0),
      coalesce(p_values->>'notes', '')
    ) returning id into v_statistic_id;
  else
    select id into v_statistic_id from public.duty_statistics
    where id = p_statistic_id and profile_id = p_member_id and slot_id = p_slot_id and duty_date = p_duty_date;
    if v_statistic_id is null then raise exception 'The statistics record could not be found.'; end if;
    update public.duty_statistics set
      no_of_clients = coalesce((p_values->>'noOfClients')::integer, 0),
      no_of_hours_worked = coalesce((p_values->>'noOfHoursWorked')::numeric, 0),
      certified_copies = coalesce((p_values->>'certifiedCopies')::integer, 0),
      statutory_declarations = coalesce((p_values->>'statutoryDeclarations')::integer, 0),
      signatures_witnessed = coalesce((p_values->>'signatureWitnessed')::integer, 0),
      affidavits = coalesce((p_values->>'affidavits')::integer, 0),
      other_duties = coalesce((p_values->>'other')::integer, 0),
      notes = coalesce(p_values->>'notes', '')
    where id = v_statistic_id;
  end if;
  return v_statistic_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_home_based_duty_statistic(p_statistic_id uuid, p_duty_date date, p_start_time time without time zone, p_values jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_desk record;
  v_statistic record;
  v_slot_id uuid;
  v_end_time time;
  v_statistic_id uuid;
  v_local_now timestamp;
begin
  if v_actor_id is null
     or not exists (select 1 from public.profiles where id = v_actor_id and status = 'Approved') then
    raise exception 'You must be an approved JP member to save Home Based Service statistics.';
  end if;
  if p_duty_date is null or p_start_time is null then
    raise exception 'A date and start time are required.';
  end if;

  select id, name, code
  into v_desk
  from public.service_desks
  where is_home_based_service
    and status = 'Active'
  limit 1;

  if not found then
    raise exception 'The Home Based Service desk is not available. Run the Home Based Service migration first.';
  end if;

  v_end_time := case
    when p_start_time >= time '23:45' then time '23:59:59'
    else (p_start_time + interval '15 minutes')::time
  end;

  -- Statistics are recorded only after the short home-based service has
  -- finished, consistent with the normal rostered-shift statistics rules.
  select now() at time zone coalesce(region.timezone, 'Pacific/Auckland')
  into v_local_now
  from public.service_desks desk
  join public.regions region on region.id = desk.region_id
  where desk.id = v_desk.id;
  if (p_duty_date + p_start_time + interval '15 minutes') > v_local_now then
    raise exception 'Statistics can be logged only after the Home Based Service has ended.';
  end if;

  if p_statistic_id is null then
    -- Each special statistic receives its own hidden slot. This preserves the
    -- existing duty_statistics foreign-key and maintenance model without
    -- creating a rostered service-desk shift.
    insert into public.duty_slots (
      desk_id, day_of_week, start_time, end_time,
      min_jps, target_jps, max_jps, status, effective_from
    ) values (
      v_desk.id, extract(dow from p_duty_date)::integer, p_start_time, v_end_time,
      1, 1, 1, 'Active', p_duty_date
    ) returning id into v_slot_id;

    insert into public.duty_statistics (
      profile_id, slot_id, duty_date,
      desk_name_snapshot, desk_code_snapshot, start_time_snapshot, end_time_snapshot,
      no_of_clients, no_of_hours_worked, certified_copies, statutory_declarations,
      signatures_witnessed, affidavits, other_duties, notes
    ) values (
      v_actor_id, v_slot_id, p_duty_date,
      v_desk.name, v_desk.code, p_start_time, v_end_time,
      coalesce((p_values->>'noOfClients')::integer, 0),
      coalesce((p_values->>'noOfHoursWorked')::numeric, 0),
      coalesce((p_values->>'certifiedCopies')::integer, 0),
      coalesce((p_values->>'statutoryDeclarations')::integer, 0),
      coalesce((p_values->>'signatureWitnessed')::integer, 0),
      coalesce((p_values->>'affidavits')::integer, 0),
      coalesce((p_values->>'other')::integer, 0),
      coalesce(p_values->>'notes', '')
    ) returning id into v_statistic_id;
  else
    select statistic.id, statistic.profile_id, statistic.slot_id
    into v_statistic
    from public.duty_statistics statistic
    join public.duty_slots slot on slot.id = statistic.slot_id
    join public.service_desks desk on desk.id = slot.desk_id
    where statistic.id = p_statistic_id
      and desk.is_home_based_service;

    if not found then
      raise exception 'The Home Based Service statistics record could not be found.';
    end if;
    if v_statistic.profile_id <> v_actor_id
       and not exists (select 1 from public.profiles where id = v_actor_id and status = 'Approved' and role = 'Registrar') then
      raise exception 'Only the JP member or a Registrar can maintain this Home Based Service record.';
    end if;

    update public.duty_slots
    set day_of_week = extract(dow from p_duty_date)::integer,
        start_time = p_start_time,
        end_time = v_end_time,
        effective_from = p_duty_date
    where id = v_statistic.slot_id;

    update public.duty_statistics
    set duty_date = p_duty_date,
        start_time_snapshot = p_start_time,
        end_time_snapshot = v_end_time,
        no_of_clients = coalesce((p_values->>'noOfClients')::integer, 0),
        no_of_hours_worked = coalesce((p_values->>'noOfHoursWorked')::numeric, 0),
        certified_copies = coalesce((p_values->>'certifiedCopies')::integer, 0),
        statutory_declarations = coalesce((p_values->>'statutoryDeclarations')::integer, 0),
        signatures_witnessed = coalesce((p_values->>'signatureWitnessed')::integer, 0),
        affidavits = coalesce((p_values->>'affidavits')::integer, 0),
        other_duties = coalesce((p_values->>'other')::integer, 0),
        notes = coalesce(p_values->>'notes', '')
    where id = v_statistic.id;

    v_statistic_id := v_statistic.id;
  end if;

  return v_statistic_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_my_profile(p_phone text, p_reminder_frequency text, p_reminder_start_date date, p_reminder_weeks integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  is_desk_admin boolean;
begin
  if auth.uid() is null then
    raise exception 'No profile was found for the signed-in user.';
  end if;

  if p_reminder_frequency not in ('NONE', 'WEEKLY', 'FORTNIGHTLY') then
    raise exception 'Invalid Desk Admin reminder frequency.';
  end if;

  if p_reminder_weeks not between 1 and 52 then
    raise exception 'Weeks to report on must be between 1 and 52.';
  end if;

  select exists (
    select 1
    from public.service_desks
    where primary_admin_id = auth.uid()
       or secondary_admin_id = auth.uid()
  ) into is_desk_admin;

  update public.profiles
  set phone = nullif(trim(coalesce(p_phone, '')), ''),
      desk_admin_reminder_frequency = case
        when is_desk_admin then p_reminder_frequency else 'NONE'
      end,
      desk_admin_reminder_start_date = case
        when is_desk_admin and p_reminder_frequency <> 'NONE' then p_reminder_start_date else null
      end,
      desk_admin_reminder_weeks = case
        when is_desk_admin then p_reminder_weeks else 4
      end
  where id = auth.uid();

  if not found then
    raise exception 'Your application profile could not be found.';
  end if;
end;
